style:
.sca-timeline-root {
	display: flex;
	flex-direction: column;
	gap: 10px;
	padding: 4px 0;
}

.sca-timeline-empty {
	color: var(--text-muted);
	padding: 12px 0;
}

.sca-timeline-root {
	position: relative;
}

.sca-card {
	position: relative;
	border: 1px solid var(--border-color);
	border-radius: var(--border-radius, 6px);
	background: var(--fg-color, #fff);
	overflow: hidden;
}

.sca-card-header {
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 8px;
	padding: 8px 12px;
	cursor: pointer;
	user-select: none;
}

.sca-card-header:hover {
	background: var(--subtle-fg, rgba(0, 0, 0, 0.02));
}

.sca-hop-tag {
	flex-shrink: 0;
	font-size: 10px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.02em;
	padding: 3px 8px;
	border-radius: 999px;
	white-space: nowrap;
}

.sca-hop-tag.sca-inbound {
	background: rgba(59, 130, 246, 0.14);
	color: #1d4ed8;
}

.sca-hop-tag.sca-outbound {
	background: rgba(139, 92, 246, 0.14);
	color: #6d28d9;
}

.sca-hop-tag.sca-lifecycle {
	background: rgba(107, 114, 128, 0.14);
	color: #374151;
	white-space: normal;
}

.sca-card-endpoint {
	font-weight: 600;
	font-size: 12px;
	white-space: normal;
	word-break: break-all;
	flex: 1 1 260px;
	min-width: 160px;
}

.sca-card-meta {
	margin-left: auto;
	display: flex;
	align-items: center;
	gap: 10px;
	font-size: 12px;
	color: var(--text-muted);
	white-space: nowrap;
}

.sca-chevron {
	transition: transform 0.15s ease;
	color: var(--text-muted);
}

.sca-card-header.sca-expanded .sca-chevron {
	transform: rotate(90deg);
}

.sca-card-body[hidden] {
	display: none;
}

.sca-card-body {
	border-top: 1px solid var(--border-color);
	padding: 10px 12px;
}

.sca-columns {
	display: flex;
	flex-wrap: wrap;
	gap: 12px;
}

.sca-column {
	flex: 1 1 280px;
	min-width: 0;
	display: flex;
	flex-direction: column;
	gap: 8px;
}

.sca-column-title {
	font-size: 11px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.02em;
	color: var(--text-muted);
	padding-bottom: 4px;
	border-bottom: 1px solid var(--border-color);
}

.sca-subcards {
	display: flex;
	flex-direction: column;
	gap: 8px;
	padding-left: 8px;
	border-left: 2px solid var(--border-color);
}

.sca-leg {
	display: flex;
	flex-direction: column;
	gap: 6px;
	padding: 8px;
	border: 1px solid var(--border-color);
	border-radius: 4px;
}

.sca-leg-meta {
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 8px;
	font-size: 11px;
	color: var(--text-muted);
}

.sca-leg-endpoint {
	font-weight: 600;
	font-size: 11px;
	word-break: break-all;
	flex: 1 1 auto;
}

.sca-hop {
	display: flex;
	flex-direction: column;
	gap: 4px;
}

.sca-hop-label {
	font-size: 11px;
	font-weight: 600;
	text-transform: uppercase;
	letter-spacing: 0.02em;
	color: var(--text-muted);
}

.sca-json {
	margin: 0;
	padding: 8px 10px;
	background: var(--subtle-fg, rgba(0, 0, 0, 0.03));
	border-radius: 4px;
	font-size: 12px;
	white-space: pre-wrap;
	word-break: break-word;
	max-height: 320px;
	overflow: auto;
}

.sca-error {
	color: var(--red-500, #d1242f);
	font-size: 12px;
}

script:
try {
	var root = root_element.querySelector(".sca-timeline-root");

	if (!cur_frm || cur_frm.doctype !== "Call Logs" || cur_frm.is_new()) {
		root.innerHTML =
			'<div class="sca-timeline-empty">' +
			__("Save this Call Log to see its audit trail.") +
			"</div>";
	} else {
		frappe.call({
			method: "shukhee_integration.api.audit.get_call_audit_timeline",
			args: { call_log: cur_frm.docname },
			callback: function (r) {
				render(root, r.message || []);
			},
			error: function () {
				root.innerHTML =
					'<div class="sca-timeline-empty text-muted">' +
					__("Could not load audit trail.") +
					"</div>";
			},
		});
	}

	function hop_labels(direction) {
		if (direction === "Inbound") {
			return { request: "Mobile → Spice", response: "Spice → Mobile" };
		}
		return { request: "Spice → Sukhee", response: "Sukhee → Spice" };
	}

	function hop_tag_class(direction) {
		return direction === "Inbound" ? "sca-inbound" : "sca-outbound";
	}

	function pretty_json(text) {
		if (!text) {
			return '<span class="text-muted">' + __("No body") + "</span>";
		}
		try {
			return frappe.utils.escape_html(JSON.stringify(JSON.parse(text), null, 2));
		} catch (e) {
			// Truncated/non-JSON payload (to_json() appends a
			// "...[truncated, N chars total]" suffix that isn't valid JSON) --
			// show it raw rather than failing to render the card.
			return frappe.utils.escape_html(text);
		}
	}

	function status_pill(status) {
		var color = status === "Success" ? "green" : "red";
		return (
			'<span class="indicator-pill ' +
			color +
			'">' +
			frappe.utils.escape_html(status || "") +
			"</span>"
		);
	}

	// Groups the flat row list into one entry per real round trip: every
	// inbound call generates a correlation_id (see audit_inbound in audit.py),
	// and every outbound call made while handling it picks up that same id --
	// so grouping by correlation_id reconstructs the full
	// Mobile -> Spice -> Sukhee -> Spice -> Mobile lifecycle of a single
	// mobile-initiated request, even though it's stored as N separate rows.
	// Rows with no correlation_id (older data logged before this field
	// existed, or a genuinely standalone outbound call) each become their
	// own single-row group, keyed by their own name so they never collide.
	function group_rows(rows) {
		var groups = {};
		var order = [];
		rows.forEach(function (row) {
			var key = row.correlation_id || "row-" + row.name;
			if (!groups[key]) {
				groups[key] = { inbound: null, outbound: [], earliest: row.logged_at };
				order.push(key);
			}
			var g = groups[key];
			if (row.logged_at && (!g.earliest || row.logged_at < g.earliest)) g.earliest = row.logged_at;
			if (row.direction === "Inbound") {
				g.inbound = row;
			} else {
				g.outbound.push(row);
			}
		});
		order.sort(function (a, b) {
			return (groups[a].earliest || "").localeCompare(groups[b].earliest || "");
		});
		return order.map(function (key) {
			var g = groups[key];
			g.outbound.sort(function (a, b) {
				return (a.logged_at || "").localeCompare(b.logged_at || "");
			});
			return g;
		});
	}

	function render_leg(row) {
		var labels = hop_labels(row.direction);
		var duration = row.duration_ms != null ? row.duration_ms + " ms" : "—";
		var status_code = row.status_code != null ? row.status_code : "—";
		var error_html = row.error
			? '<div class="sca-error">' + frappe.utils.escape_html(row.error) + "</div>"
			: "";

		return (
			'<div class="sca-leg">' +
			'<div class="sca-leg-meta">' +
			status_pill(row.status) +
			'<span class="sca-leg-endpoint">' + frappe.utils.escape_html(row.endpoint || "") + "</span>" +
			"<span>" + frappe.utils.escape_html(String(status_code)) + "</span>" +
			"<span>" + frappe.utils.escape_html(duration) + "</span>" +
			"</div>" +
			error_html +
			'<div class="sca-hop">' +
			'<span class="sca-hop-label">' + frappe.utils.escape_html(labels.request) + "</span>" +
			'<pre class="sca-json">' + pretty_json(row.request_payload) + "</pre>" +
			"</div>" +
			'<div class="sca-hop">' +
			'<span class="sca-hop-label">' + frappe.utils.escape_html(labels.response) + "</span>" +
			'<pre class="sca-json">' + pretty_json(row.response_payload) + "</pre>" +
			"</div>" +
			"</div>"
		);
	}

	function render_lifecycle_card(group) {
		var inbound = group.inbound;
		var outbound = group.outbound;
		var header_row = inbound || outbound[0];
		var duration = header_row.duration_ms != null ? header_row.duration_ms + " ms" : "—";
		var status_code = header_row.status_code != null ? header_row.status_code : "—";
		var logged_at = header_row.logged_at ? frappe.datetime.str_to_user(header_row.logged_at) : "";
		// Overall status: if there's an inbound leg, its own status reflects
		// whether Spice's response back to Mobile succeeded -- the outcome
		// that actually matters to the caller, even if an individual outbound
		// leg inside it failed and was handled. Falls back to "did every
		// outbound leg succeed" only when there's no inbound leg to judge by.
		var overall_status = inbound
			? inbound.status
			: outbound.every(function (o) {
					return o.status === "Success";
			  })
			? "Success"
			: "Failed";

		var mobile_col = inbound
			? render_leg(inbound)
			: '<div class="sca-timeline-empty">' + __("No inbound call recorded for this request.") + "</div>";

		var sukhee_col = outbound.length
			? outbound.map(render_leg).join("")
			: '<div class="sca-timeline-empty">' + __("No outbound calls for this request.") + "</div>";

		return (
			'<div class="sca-card">' +
			'<div class="sca-card-header">' +
			'<span class="sca-chevron">▶</span>' +
			'<span class="sca-hop-tag sca-lifecycle">' + __("Mobile ↔ Spice ↔ Sukhee") + "</span>" +
			'<span class="sca-card-endpoint">' + frappe.utils.escape_html(inbound ? inbound.endpoint : header_row.endpoint || "") + "</span>" +
			'<span class="sca-card-meta">' +
			status_pill(overall_status) +
			"<span>" + frappe.utils.escape_html(String(status_code)) + "</span>" +
			"<span>" + frappe.utils.escape_html(duration) + "</span>" +
			"<span>" + frappe.utils.escape_html(logged_at) + "</span>" +
			"</span>" +
			"</div>" +
			'<div class="sca-card-body" hidden>' +
			'<div class="sca-columns">' +
			'<div class="sca-column">' +
			'<div class="sca-column-title">' + __("Mobile ↔ Spice") + "</div>" +
			mobile_col +
			"</div>" +
			'<div class="sca-column">' +
			'<div class="sca-column-title">' + __("Spice ↔ Sukhee") + "</div>" +
			sukhee_col +
			"</div>" +
			"</div>" +
			"</div>" +
			"</div>"
		);
	}

	// The endpoint that identifies a lifecycle group -- the inbound call's
	// dotted path, or (for the rare group with no inbound leg at all) its
	// first outbound leg's endpoint.
	function group_endpoint(group) {
		if (group.inbound) return group.inbound.endpoint;
		return group.outbound[0] ? group.outbound[0].endpoint : "";
	}

	// A second pass over the correlation-id groups from group_rows(): bundles
	// every lifecycle instance of the SAME endpoint together (e.g. get_consultation_status
	// polled 20+ times becomes one bucket of 20 instances) so the timeline
	// shows one entry per distinct API, not one per poll. Order is preserved
	// by each bucket's first occurrence, matching the chronological groups
	// passed in.
	function group_by_endpoint(groups) {
		var buckets = {};
		var order = [];
		groups.forEach(function (group) {
			var key = group_endpoint(group);
			if (!buckets[key]) {
				buckets[key] = [];
				order.push(key);
			}
			buckets[key].push(group);
		});
		return order.map(function (key) {
			return { endpoint: key, instances: buckets[key] };
		});
	}

	// A bucket with exactly one instance renders as a plain lifecycle card
	// (no point wrapping a single call in its own "1x calls" shell). A
	// bucket with more renders as one collapsible outer card whose body is a
	// stack of the individual lifecycle cards as sub-cards -- the same
	// delegated click handler below handles both the outer header and each
	// sub-card's own header, since both follow the identical
	// .sca-card-header + .sca-card-body[hidden] pattern.
	function render_endpoint_bucket(bucket) {
		if (bucket.instances.length === 1) {
			return render_lifecycle_card(bucket.instances[0]);
		}

		var last = bucket.instances[bucket.instances.length - 1];
		var last_header = last.inbound || last.outbound[0];
		var logged_at = last_header.logged_at ? frappe.datetime.str_to_user(last_header.logged_at) : "";
		var overall_status = bucket.instances.every(function (group) {
			var header_row = group.inbound || group.outbound[0];
			return header_row.status === "Success";
		})
			? "Success"
			: "Failed";

		var subcards = bucket.instances.map(render_lifecycle_card).join("");

		return (
			'<div class="sca-card sca-endpoint-group">' +
			'<div class="sca-card-header">' +
			'<span class="sca-chevron">▶</span>' +
			'<span class="sca-hop-tag sca-lifecycle">' +
			bucket.instances.length +
			"× " +
			__("calls") +
			"</span>" +
			'<span class="sca-card-endpoint">' + frappe.utils.escape_html(bucket.endpoint) + "</span>" +
			'<span class="sca-card-meta">' +
			status_pill(overall_status) +
			"<span>" + __("last") + ": " + frappe.utils.escape_html(logged_at) + "</span>" +
			"</span>" +
			"</div>" +
			'<div class="sca-card-body" hidden>' +
			'<div class="sca-subcards">' + subcards + "</div>" +
			"</div>" +
			"</div>"
		);
	}

	function render(el, rows) {
		if (!rows.length) {
			el.innerHTML =
				'<div class="sca-timeline-empty">' + __("No audit trail yet for this call.") + "</div>";
			return;
		}
		var groups = group_rows(rows);
		var buckets = group_by_endpoint(groups);
		el.innerHTML = buckets.map(render_endpoint_bucket).join("");
	}

	root.addEventListener("click", function (e) {
		var header = e.target.closest(".sca-card-header");
		if (!header) return;
		header.nextElementSibling.toggleAttribute("hidden");
		header.classList.toggle("sca-expanded");
	});
} catch (e) {
	console.error("Shukhee Call Audit Timeline render failed:", e);
}
